 39	function copyDir(src, dest) {
 40	  if (!fs.existsSync(dest)) fs.mkdirSync(dest, { recursive: true });
 41	  const entries = fs.readdirSync(src, { withFileTypes: true });
 42	  for (const entry of entries) {
 43	    const srcPath = path.join(src, entry.name);
 44	    const destPath = path.join(dest, entry.name);
 45	    if (entry.isDirectory()) {
 46	      copyDir(srcPath, destPath);
 47	    } else {
 48	      fs.copyFileSync(srcPath, destPath);
 49	    }
 50	  }
 51	}
