 56	
 57	  for (const size of ICON_SIZES) {
 58	    await sharp(svgBuffer)
 59	      .resize(size, size)
 60	      .png()
 61	      .toFile(path.join(SRC, 'icons', `icon${size}.png`));
 62	    console.log(`  Generated icon${size}.png`);
 63	  }
 64	}
