 66	async function build(browser) {
 67	  const distPath = path.join(DIST, browser);
 68	  console.log(`\nBuilding for ${browser}...`);
 69	
 70	  if (fs.existsSync(distPath)) {
 71	    fs.rmSync(distPath, { recursive: true });
 72	  }
 73	  fs.mkdirSync(distPath, { recursive: true });
 74	
 75	  for (const file of COPY_FILES) {
 76	    const src = path.join(SRC, file);
 77	    const dest = path.join(distPath, file);
 78	    if (fs.existsSync(src)) {
 79	      fs.copyFileSync(src, dest);
 80	      console.log(`  Copied ${file}`);
 81	    }
 82	  }
 83	
 84	  for (const dir of COPY_DIRS) {
