 86	    if (fs.existsSync(src)) {
 87	      copyDir(src, path.join(distPath, dir));
 88	      const svg = path.join(distPath, dir, 'icon.svg');
 89	      if (fs.existsSync(svg)) fs.unlinkSync(svg);
 90	      console.log(`  Copied ${dir}/`);
 91	    }
 92	  }
